/**
 * robots.txt. Points crawlers at the production sitemap index generated by
 * @astrojs/sitemap. The sitemap URL is absolute, built from the configured
 * site. Preview deployments should additionally send X-Robots-Tag: noindex at
 * the host level (see docs/DEPLOYMENT_GUIDE.md) — robots.txt alone is not
 * enough to keep a preview out of the index.
 */
import type { APIContext } from 'astro';

export async function GET(context: APIContext) {
  const site = context.site?.toString() ?? 'https://example.com/';
  const sitemapUrl = new URL('sitemap-index.xml', site).toString();
  const body = `User-agent: *
Allow: /

Sitemap: ${sitemapUrl}
`;
  return new Response(body, {
    headers: { 'Content-Type': 'text/plain; charset=utf-8' },
  });
}
